switch (platform) {
    case 'ios':
      return ['ios'];
    case 'android':
      return ['android'];
    case 'all':
      return loose || process.platform !== 'win32' ? ['android', 'ios'] : ['android'];
    default:
      return [platform as ModPlatform];
  }

switch (platform) {
      case 'android': {
        const { expoRunAndroid } = await import('./android/index.js');
        return expoRunAndroid(argsWithoutPlatform);
      }

      case 'ios': {
        const { expoRunIos } = await import('./ios/index.js');
        return expoRunIos(argsWithoutPlatform);
      }
      case 'harmony': {
        const { expoRunHarmony } = await import('./harmony/index.js');
        return expoRunHarmony(argsWithoutPlatform);
      }

      default:
        throw new CommandError('UNSUPPORTED_PLATFORM', `Unsupported platform: ${platform}`);
    }

helpCalls.text:
printHelp(
      `Log out of an Expo account`,
      `npx expo logout`,
      // options
      `-h, --help    Usage info`
    )

printHelp(
      `Sign up for a new Expo account`,
      `npx expo register`,
      // Options
      `-h, --help    Usage info`
    )

Log.exit(
      chalk`
  {bold Description}
    Run the native Android app locally

  {bold Usage}
    $ npx expo run:android <dir>

  {bold Options} 
    --no-build-cache       Clear the native build cache
    --no-install           Skip installing dependencies
    --no-bundler           Skip starting the bundler
    --app-id <appId>       Custom Android application ID to launch.
    --variant <name>       Build variant or product flavor and build variant. {dim Default: debug}
    --binary <path>        Path to existing .apk or .aab to install.
    -d, --device [device]  Device name to run the app on
    -p, --port <port>      Port to start the dev server on. {dim Default: 8081}
    -h, --help             Output usage information
`,
      0
    )

Log.exit(
    chalk`
  {bold Info}
    ${info}

  {bold Usage}
    {dim $} ${usage}

  {bold Options}
    ${options.split('\n').join('\n    ')}
` + extra,
    0
  )

parsers.text:
arg(
  {
    // Types
    '--version': Boolean,
    '--help': Boolean,
    // NOTE(EvanBacon): This is here to silence warnings from processes that
    // expect the global expo-cli.
    '--non-interactive': Boolean,

    // Aliases
    '-v': '--version',
    '-h': '--help',
  },
  {
    permissive: true,
  }
)

assertArgs(
    {
      // Types
      '--help': Boolean,
      '--full': Boolean,
      '--json': Boolean,
      '--type': String,
      // Aliases
      '-h': '--help',
      '-t': '--type',
    },
    argv
  )

assertWithOptionsArgs(
    {
      // Other options are parsed manually.
      '--help': Boolean,
      // Aliases
      '-h': '--help',
    },
    {
      argv,
      // Allow other options, we'll throw an error if unexpected values are passed.
      permissive: true,
    }
  )

assertWithOptionsArgs(rawArgsMap, {
    argv,
    permissive: true,
  })

assertArgs(
    {
      // Types
      '--help': Boolean,
      '--clear': Boolean,
      '--dump-assetmap': Boolean,
      '--dev': Boolean,
      '--source-maps': Boolean,
      '--max-workers': Number,
      '--output-dir': String,
      '--platform': [String],
      '--no-minify': Boolean,
      '--no-bytecode': Boolean,
      '--no-ssg': Boolean,
      '--api-only': Boolean,
      '--unstable-hosted-native': Boolean,

      // Hack: This is added because EAS CLI always includes the flag.
      // If supplied, we'll do nothing with the value, but at least the process won't crash.
      // Note that we also don't show this value in the `--help` prompt since we don't want people to use it.
      '--experimental-bundle': Boolean,

      // Aliases
      '-h': '--help',
      '-s': '--source-maps',
      // '-d': '--dump-assetmap',
      '-c': '--clear',
      '-p': '--platform',
      // Interop with Metro docs and RedBox errors.
      '--reset-cache': '--clear',

      // Deprecated
      '--dump-sourcemap': '--source-maps',
    },
    argv
  )

assertArgs(
    {
      // Types
      '--help': Boolean,
      '--clear': Boolean,
      '--dev': Boolean,
      // Aliases
      '-h': '--help',
      '-c': '--clear',
    },
    argv
  )

assertWithOptionsArgs(
    {
      // Other options are parsed manually.
      '--help': Boolean,
      '--json': Boolean,
      // Aliases
      '-h': '--help',
    },
    {
      argv,
      // Allow other options, we'll throw an error if unexpected values are passed.
      permissive: true,
    }
  )

assertWithOptionsArgs(
    {
      // Other options are parsed manually.
      '--help': Boolean,
      '--no-cache': Boolean,
      '--fix': Boolean,
      '--quiet': Boolean,
      '--no-ignore': Boolean,

      // Aliases
      '-h': '--help',
    },
    {
      argv,
      // Allow other options, we'll throw an error if unexpected values are passed.
      permissive: true,
    }
  )

assertArgs(
    {
      // Types
      '--help': Boolean,
      '--username': String,
      '--password': String,
      '--otp': String,
      '--sso': Boolean,
      // Aliases
      '-h': '--help',
      '-u': '--username',
      '-p': '--password',
      '-s': '--sso',
    },
    argv
  )

assertArgs(
    {
      // Types
      '--help': Boolean,
      // Aliases
      '-h': '--help',
    },
    argv
  )

assertArgs(
    {
      // Types
      '--help': Boolean,
      // Aliases
      '-h': '--help',
    },
    argv
  )

assertWithOptionsArgs(rawArgsMap, {
    argv,

    permissive: true,
  })

resolveStringOrBooleanArgsAsync(argv ?? [], rawArgsMap, {
    '--device': Boolean,
    '-d': '--device',
  })

assertWithOptionsArgs(
    {
      // Types
      '--help': Boolean,
      // Aliases
      '-h': '--help',
    },
    {
      argv,
      // Allow additional flags for both android and ios commands
      permissive: true,
    }
  )

assertWithOptionsArgs(rawArgsMap, {
    argv,

    permissive: true,
  })

resolveStringOrBooleanArgsAsync(argv ?? [], rawArgsMap, {
    '--scheme': Boolean,
    '--device': Boolean,
    '-d': '--device',
  })

assertArgs(
    {
      // Types
      '--help': Boolean,
      '--port': Number,

      // Aliases
      '-h': '--help',
    },
    argv
  )

assertArgs(
    {
      // Types
      '--help': Boolean,
      // Aliases
      '-h': '--help',
    },
    argv
  )

